examples.template:
Grid(alignment: .topLeading, horizontalSpacing: theme.spacing.space6, verticalSpacing: theme.spacing.space4) {
    GridRow {
        LabeledContent({{items.0.term}}, value: {{items.0.value}})
        LabeledContent({{items.1.term}}, value: {{items.1.value}})
    }
    GridRow {
        LabeledContent({{items.2.term}}, value: {{items.2.value}})
        LabeledContent({{items.3.term}}, value: {{items.3.value}})
    }
    GridRow {
        LabeledContent({{items.4.term}}, value: {{items.4.value}})
            .gridCellColumns({{items.4.wide}} ? {{columns}} : 1)
    }
}
.labeledContentStyle(.monarch)

examples.code:
Grid(alignment: .topLeading, horizontalSpacing: theme.spacing.space6, verticalSpacing: theme.spacing.space4) {
    GridRow {
        LabeledContent("Owner", value: "Ada Lovelace")
        LabeledContent("Stage", value: "Proposal")
