VStack(alignment: .leading, spacing: theme.spacing.space3) {
    LabeledContent("Customer ID") {
        HStack(spacing: theme.spacing.space1) {
            Text("cus_01HZX4Q8").monarchTextStyle(.code)
            MonarchCopyButton(value: "cus_01HZX4Q8", target: "Customer ID", variant: .ghost, size: .sm, isIconOnly: true)
        }
    }
    LabeledContent("Notes") {
        MonarchTruncatedText("Renewal depends on the security review in May.", lineLimit: 1)
    }
}
.labeledContentStyle(.monarch(.inline))

